/** All languages this plugin ships, in one call to the host locale service. */
export const dictionaries: Record<string, Record<string, string>> = {
  zh, en, ja, ko, fr, de, it, ru, es, pt,
}

/**
 * The bound translator handed over by the client entry after registration.
 * Kept at module scope so helper modules (not just components) can translate.
 */
let translate: ((key: string) => string) | null = null

/** Install the host-backed lookup; `null` unbinds it (tests, SSR, early boot). */
export function installTranslate(fn: ((key: string) => string) | null): void {
  translate = fn
}

const zhLookup: Record<string, string> = zh

/**
 * Translate `key` inside {@link NS}, interpolating `{placeholder}` params.
 *
 * Fallback chain: active locale → the `zh` source copy → the raw key. Falling
 * back to `zh` (instead of the key) keeps every string readable — and keeps the
 * existing unit tests, which assert the Chinese copy — green when no locale
 * service is installed.
 */
export function t(key: string, params?: Record<string, string | number>): string {
  let text = key
  if (translate !== null) {
    try {
      const bound = translate(key)
      if (bound !== undefined && bound !== key) text = bound
    } catch {
      text = key
    }
  }
  if (text === key) text = zhLookup[key] ?? key
  if (params !== undefined) {
    for (const [name, value] of Object.entries(params)) {
      text = text.replaceAll(`{${name}}`, String(value))
    }
  }
  return text
}
