export type SettingsLanguage = 'zh' | 'en' | 'ja' | 'ko' | 'fr' | 'de' | 'it' | 'ru' | 'es' | 'pt';

const dictionaries: Record<SettingsLanguage, SettingsCopy> = { zh, en, ja, ko, fr, de, it, ru, es, pt };

const languageByPrefix: ReadonlyArray<readonly [string, SettingsLanguage]> = [
  ['zh', 'zh'], ['en', 'en'], ['ja', 'ja'], ['ko', 'ko'], ['fr', 'fr'], ['de', 'de'], ['it', 'it'], ['ru', 'ru'], ['es', 'es'], ['pt', 'pt'],
];

export function settingsLanguage(tag: string | undefined): SettingsLanguage {
  const lower = (tag ?? '').toLowerCase();
  for (const [prefix, language] of languageByPrefix) {
    if (lower.startsWith(prefix)) return language;
  }
  return 'en';
}

export function settingsCopyFor(tag: string | undefined): SettingsCopy {
  return dictionaries[settingsLanguage(tag)];
}
